package kec.allocator;
import java.io.*;import java.nio.file.*;import java.util.*;
public class FileProcessor {
 public List<StartupProposal> readCsv(Path path)throws IOException{Map<String,StartupProposal> map=new LinkedHashMap<>();try(BufferedReader br=Files.newBufferedReader(path)){String line;int no=0;while((line=br.readLine())!=null){no++;if(no==1&&line.toLowerCase(Locale.ROOT).startsWith("proposalcode,"))continue;if(line.isBlank())continue;String[] a=line.split(",",-1);if(a.length!=11)throw new IOException("Line "+no+": expected 11 columns");try{String code=a[0].trim().toUpperCase();if(!code.matches("KEC-INC-\\d{4}"))throw new IllegalArgumentException("Invalid proposal code");String cat=a[2].trim().toUpperCase();if(!Set.of("TECH HARDWARE","SOFTWARE","SOFTWARE / SAAS","SAAS","SOCIAL INNOVATION").contains(cat))throw new IllegalArgumentException("Unknown category: "+cat);StartupProposal p=map.get(code);if(p==null){p=new StartupProposal();p.code=code;p.name=required(a[1]);p.category=cat;p.business=num(a[3],0,100);p.prototype=num(a[4],0,100);p.pitch=num(a[5],0,100);p.impact=num(a[6],0,100);p.feasibility=num(a[7],0,100);map.put(code,p);}else if(!p.name.equals(required(a[1]))||!p.category.equals(cat))throw new IllegalArgumentException("Proposal rows must have same name/category");String student=required(a[8]);double sgpa=num(a[9],0,10);if(!a[10].trim().equalsIgnoreCase("true")&&!a[10].trim().equalsIgnoreCase("false"))throw new IllegalArgumentException("backlogCleared must be true/false");boolean clear=Boolean.parseBoolean(a[10].trim());if(p.founders.stream().noneMatch(f->f.name().equalsIgnoreCase(student)))p.founders.add(new StartupProposal.Founder(student,sgpa,clear));}catch(RuntimeException e){throw new IOException("Line "+no+": "+e.getMessage(),e);}}}if(map.isEmpty())throw new IOException("No proposal records found");return new ArrayList<>(map.values());}
 private static String required(String s){String v=s.trim().replaceAll("[\\p{Cntrl}]","");if(v.isBlank())throw new IllegalArgumentException("Required text is empty");return v;}
 private static double num(String s,double min,double max){double v=Double.parseDouble(s.trim());if(!Double.isFinite(v)||v<min||v>max)throw new IllegalArgumentException("Number must be between "+min+" and "+max);return v;}
 public void letters(List<String[]> rows,Path dir)throws IOException{Files.createDirectories(dir);for(String[] r:rows){String code=r[0].replaceAll("[^A-Za-z0-9_-]","_");String body="KEC STUDENT INNOVATION & STARTUP SEED GRANT\nSANCTION / EVALUATION LETTER\n\nProposal Code: "+r[0]+"\nStartup Name: "+r[1]+"\nFinal Score: "+r[2]+"\nGrant Tier: "+r[3]+"\nGrant Amount: Rs. "+r[4]+"\nApproval Status: "+r[5]+"\nDisbursement Status: "+r[6]+"\n";Files.writeString(dir.resolve(code+"_sanction.txt"),body);}}
}
